description:
Implement a `DeepReadonly<T>` utility type that recursively makes all properties (and nested properties) readonly.

**Example:**
```ts
type Config = DeepReadonly<{ host: string; db: { port: number } }>;
// { readonly host: string; readonly db: { readonly port: number } }
```

starter_code:
export type DeepReadonly<T> = // your type here

// Helper function to test your type (do not change)
export function freeze<T>(obj: T): DeepReadonly<T> {
  return Object.freeze(obj) as DeepReadonly<T>;
}

test_suite:
test('freeze returns same value', () => {
  const obj = freeze({ x: 1, nested: { y: 2 } });
  expect(obj.x).toBe(1);
  expect(obj.nested.y).toBe(2);
});

test('type-level: top properties are readonly', () => {
  type T = DeepReadonly<{ a: number }>;
  type IsReadonly = T extends { readonly a: number } ? true : false;
  const check: IsReadonly = true;
  expect(check).toBe(true);
});

test('type-level: nested properties are readonly', () => {
  type T = DeepReadonly<{ inner: { b: string } }>;
  type IsReadonly = T extends { readonly inner: { readonly b: string } } ? true : false;
  const check: IsReadonly = true;
  expect(check).toBe(true);
});

// __hidden__
test('primitives pass through unchanged', () => {
  type T = DeepReadonly<string>;
  const s: T = 'hello';
  expect(s).toBe('hello');
});

solution:
export type DeepReadonly<T> = T extends (infer U)[]
  ? ReadonlyArray<DeepReadonly<U>>
  : T extends object
  ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
  : T;

export function freeze<T>(obj: T): DeepReadonly<T> {
  return Object.freeze(obj) as DeepReadonly<T>;
}
